/// A verb form: which cell of its conjugation.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Cell {
    /// An indicative.
    Indicative(crate::Voice, crate::Tense, crate::Person, crate::Number),
    /// A subjunctive.
    Subjunctive(
        crate::Voice,
        crate::SubjunctiveTense,
        crate::Person,
        crate::Number,
    ),
    /// A present imperative (the second person only).
    PresentImperative(crate::Voice, crate::Number),
    /// A future imperative.
    FutureImperative(crate::Voice, crate::ImperativePerson, crate::Number),
    /// An infinitive (the perfect passive and the futures are phrases: `amātum esse`, `amātūrum esse`, `amātum īrī`).
    Infinitive(crate::Voice, crate::InfinitiveTense),
    /// A participle's citation form; decline it with `adjective`. The future passive participle is the gerundive.
    Participle(crate::Participle),
    /// The gerund (genitive, dative, accusative, ablative).
    Gerund(crate::Case),
    /// The supine (accusative and ablative).
    Supine(crate::Case),
}

impl Cell {
    /// Its place in a paradigm: its group's first cell, then its values
    /// counted in order, the last fastest.
    pub const fn index(self) -> usize {
        match self {
            Cell::Indicative(voice, tense, person, number) => {
                cell::ACT_PRES_1_SG as usize
                    + ((voice as usize * 6 + tense as usize) * 3 + person as usize) * 2
                    + number as usize
            }
            Cell::Subjunctive(voice, subjunctive_tense, person, number) => {
                cell::SUBJUNCTIVE_ACT_PRES_1_SG as usize
                    + ((voice as usize * 4 + subjunctive_tense as usize) * 3 + person as usize) * 2
                    + number as usize
            }
            Cell::PresentImperative(voice, number) => {
                cell::PRESENT_IMPERATIVE_ACT_SG as usize + voice as usize * 2 + number as usize
            }
            Cell::FutureImperative(voice, imperative_person, number) => {
                cell::FUTURE_IMPERATIVE_ACT_2_SG as usize
                    + (voice as usize * 2 + imperative_person as usize) * 2
                    + number as usize
            }
            Cell::Infinitive(voice, infinitive_tense) => {
                cell::INFINITIVE_ACT_PRES as usize + voice as usize * 3 + infinitive_tense as usize
            }
            Cell::Participle(participle) => {
                cell::PARTICIPLE_PRES_ACT as usize + participle as usize
            }
            Cell::Gerund(case) => cell::GERUND_NOM as usize + case as usize,
            Cell::Supine(case) => cell::SUPINE_NOM as usize + case as usize,
        }
    }
}

impl From<(crate::Voice, crate::Tense, crate::Person, crate::Number)> for Cell {
    fn from(
        (voice, tense, person, number): (crate::Voice, crate::Tense, crate::Person, crate::Number),
    ) -> Self {
        Cell::Indicative(voice, tense, person, number)
    }
}

impl
    From<(
        crate::Voice,
        crate::SubjunctiveTense,
        crate::Person,
        crate::Number,
    )> for Cell
{
    fn from(
        (voice, subjunctive_tense, person, number): (
            crate::Voice,
            crate::SubjunctiveTense,
            crate::Person,
            crate::Number,
        ),
    ) -> Self {
        Cell::Subjunctive(voice, subjunctive_tense, person, number)
    }
}

impl From<(crate::Voice, crate::Number)> for Cell {
    fn from((voice, number): (crate::Voice, crate::Number)) -> Self {
        Cell::PresentImperative(voice, number)
    }
}

impl From<(crate::Voice, crate::ImperativePerson, crate::Number)> for Cell {
    fn from(
        (voice, imperative_person, number): (crate::Voice, crate::ImperativePerson, crate::Number),
    ) -> Self {
        Cell::FutureImperative(voice, imperative_person, number)
    }
}

impl From<(crate::Voice, crate::InfinitiveTense)> for Cell {
    fn from((voice, infinitive_tense): (crate::Voice, crate::InfinitiveTense)) -> Self {
        Cell::Infinitive(voice, infinitive_tense)
    }
}

impl From<crate::Participle> for Cell {
    fn from(participle: crate::Participle) -> Self {
        Cell::Participle(participle)
    }
}

/// A verb to inflect: its lemma, and what you know of it. The more you
/// tell, the surer its forms.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Verb<'w> {
    lemma: &'w str,
    given: Vec<(usize, &'w str)>,
    full: bool,
}

impl<'w> Verb<'w> {
    /// The verb `lemma`, as the dictionary writes it.
    #[must_use]
    pub fn new(lemma: &'w str) -> Self {
        Verb {
            lemma,
            given: Vec::new(),
            full: false,
        }
    }

    /// One of its forms you know (a principal part): readings that disagree
    /// with it are dropped.
    #[must_use]
    pub fn given(mut self, cell: impl Into<Cell>, form: &'w str) -> Self {
        self.given.push((cell.into().index(), form));
        self
    }

    /// Its lemma is spelled with every mark the dictionary writes, so
    /// none is hidden (without this, a lemma typed without marks may be
    /// missing some, and its forms are less sure).
    #[must_use]
    pub fn spelled_in_full(mut self) -> Self {
        self.full = true;
        self
    }

    fn known(&self) -> Known<'_> {
        Known {
            forms: &self.given,
            inherent: &[],
            full: self.full,
        }
    }

    /// Its likeliest form in `cell`.
    #[must_use]
    pub fn form(&self, cell: impl Into<Cell>) -> String {
        GRAMMAR.best(self.lemma, cell.into().index(), &self.known())
    }

    /// Every form it may have in `cell`, likeliest first, each with its
    /// probability and why.
    #[must_use]
    pub fn candidates(&self, cell: impl Into<Cell>) -> Vec<Candidate<'static>> {
        GRAMMAR.candidates(self.lemma, cell.into().index(), &self.known())
    }

    /// The conjugations it may follow, likeliest first, each with its probability
    /// and why.
    #[must_use]
    pub fn conjugation(&self) -> Vec<Reading<'static, 'static, Conjugation>> {
        GRAMMAR.readings(self.lemma, &self.known())
    }
}
